import os, json
HERE = os.path.dirname(os.path.abspath(__file__)); REPO = os.path.abspath(os.path.join(HERE, '..', '..'))
# Divisional chart readings (S8, layer schema v1.1). One table per varga; the text is composed from the app's own varga data
# (chart.vargas[key]: ascendantSign, houses, planetVargaSign) + dignity + the planet/house/sign tables of VMF and VDB.
V = {
 'D9':  dict(name='Navamsa (D9)', short='marriage and values', noun='marriage, partnership and the values you grow into', houses=[7, 9], key=['Venus', 'Jupiter'],
             intro='The navamsa is the chart of partnership and of the values you grow into. It is read as the inner strength behind your birth chart: a planet that is comfortable here tends to keep its promise in the long run.',
             lagna='This is where your closest partnerships and your deeper values begin to take shape.', asks=['Have your values or what you want from a partner changed a lot between your twenties and now?', 'Do your closest bonds feel stronger over time than they did at first?']),
 'D10': dict(name='Dashamsa (D10)', short='career', noun='career and public standing', houses=[10], key=['Sun', 'Saturn', 'Mercury'],
             intro='The dashamsa zooms in on your working life: how you build a reputation, deal with authority and carry responsibility.',
             lagna='This is how your working life tends to begin and how you present your effort.', asks=['Has your reputation grown more from steady work than from sudden breaks?', 'Do you do your best work when you carry real responsibility?']),
 'D7':  dict(name='Saptamsa (D7)', short='children and creation', noun='children, students and what you create', houses=[5], key=['Jupiter'],
             intro='The saptamsa zooms in on children, students and the things you bring into the world and look after.',
             lagna='This is how you tend to approach nurturing, teaching and creating.', asks=['Do you feel most at ease when you are guiding someone younger or building something of your own?', 'Has timing around family or creative work followed its own pace rather than your plans?']),
 'D4':  dict(name='Chaturthamsa (D4)', short='home and property', noun='home, property and settled comfort', houses=[4], key=['Moon', 'Mars'],
             intro='The chaturthamsa zooms in on home, property, vehicles and the kind of comfort that lasts.',
             lagna='This is how you tend to approach settling down and making a place your own.', asks=['Do you feel most at peace in a home you have shaped yourself?', 'Have property or moving decisions taken more time than you expected?']),
 'D24': dict(name='Siddhamsa (D24)', short='learning', noun='learning, education and skill', houses=[4, 5], key=['Mercury', 'Jupiter'],
             intro='The siddhamsa zooms in on study, skill and the way your mind builds knowledge.',
             lagna='This is how you tend to approach study and the building of skill.', asks=['Do you learn best by practising and teaching rather than by reading alone?', 'Has a particular subject or skill kept coming back to you over the years?']),
 'D20': dict(name='Vimshamsa (D20)', short='spiritual life', noun='spiritual practice and inner growth', houses=[9, 12], key=['Jupiter', 'Ketu'],
             intro='The vimshamsa zooms in on faith, practice and the quiet side of life.',
             lagna='This is how you tend to approach practice, belief and time alone.', asks=['Do quiet time and reflection steady you more than activity does?', 'Has your sense of meaning changed over the years, and did that help you?']),
}
ORDER = ['D9', 'D10', 'D7', 'D4', 'D24', 'D20']
DATA = dict(schema='layer-v1.1', order=ORDER, vargas=V,
            note='A divisional chart zooms in on one area. Read it together with the birth chart: where both agree, the theme tends to be steady; where they differ, the difference is worth noticing.')
HEAD = '''/* ============================================================================
   GENERATED by tools/reading_gen (edit the table in tools/reading_gen/build_vg.py, then run tools/reading_gen/regen.sh). Do not hand-edit this file.
   DIVISIONAL CHART READINGS (VGR): D9, D10, D7, D4, D24, D20 read in plain language, layer schema v1.1.
   VGR.chart(chart, key) -> { key, name, short, noun, score, band, bandTone, lagna{sign,text}, houses[{house,sign,lord,lordHouse,lordDignity,occupants,text}],
                              planets[{planet, sign, house, dignity, strong, weak, vargottama, key, text}], summary{strong[],weak[],vargottama[],text}, questions[], paragraphs[{h,text}], text }
   VGR.all(chart) -> the six charts in order.
   All positions come from chart.vargas[key] (the app's own varga engine); dignity from getDignity(); texts from VMF (planet x house x sign) and VDB (signs).
   Needs js/87 (VDB), js/90 (VMF). Tests: tests/varga_reading_test.py.
   ============================================================================ */
const VGR_DATA = '''
API = r'''

window.VGR = (function(D){
  'use strict';
  if (typeof VDB === 'undefined' || typeof VMF === 'undefined' || !VMF) return null;
  const SIGN = ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'];
  const PL = ['Sun','Moon','Mars','Mercury','Jupiter','Venus','Saturn','Rahu','Ketu'], BEN = ['Jupiter','Venus','Mercury','Moon'];
  const ordn = n => n + (['th','st','nd','rd'][(n % 100 > 10 && n % 100 < 14) ? 0 : Math.min(n % 10, 4) % 4] || 'th');
  const nm = arr => arr.length < 2 ? arr.join('') : arr.slice(0, -1).join(', ') + ' and ' + arr[arr.length - 1];
  const lc = s => s.charAt(0).toLowerCase() + s.slice(1), cap = s => s.charAt(0).toUpperCase() + s.slice(1), clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const DIG = { Exalted: 1, OwnSign: 1, Moolatrikona: 1, Friend: .35, Neutral: 0, Enemy: -.35, Debilitated: -1 };
  const BANDS = [[62, 'Strong', 'g'], [50, 'Steady', 'g'], [38, 'Mixed', ''], [0, 'Needs care', 'b']];
  const words = t => (t.match(/\S+/g) || []).length;

  function chart(c, key){
    const A = D.vargas[key], V = c.vargas && c.vargas[key]; if (!A || !V) return null;
    const lagSign = V.houses[0].sign, S = VDB.data.signs, hs = V.houses, pvs = V.planetVargaSign;
    const houseOfSign = s => ((s - lagSign + 12) % 12) + 1;
    const dg = n => { const s = pvs[n]; const d = (typeof getDignity === 'function') ? getDignity(n, s, 15) : null; return d && d.status || 'Neutral'; };
    // ---- planets
    const planets = PL.filter(n => pvs[n] != null && c.planets[n]).map(n => {
      const sIdx = pvs[n], h = houseOfSign(sIdx), st = dg(n), strong = st === 'Exalted' || st === 'OwnSign' || st === 'Moolatrikona', weak = st === 'Debilitated', vg = c.planets[n].sign === sIdx, key2 = A.key.includes(n);
      const ruled = []; for (let k = 1; k <= 12; k++) if (S[(lagSign + k - 1) % 12].lord === n) ruled.push(k);
      const m = VMF.placement(n, h, sIdx, st), B = VMF.data.behave[n];
      const tag = strong ? ', in a strong sign' : weak ? ', in a weaker sign' : '', vtag = vg ? ' It is in the same sign as in your birth chart (vargottama), which tends to make its message steadier.' : '';
      const role = key2 ? ` As a natural significator for ${A.short}, it carries extra weight here.` : '';
      const rule = ruled.some(k => A.houses.includes(k)) ? ` It rules the ${nm(ruled.filter(k => A.houses.includes(k)).map(ordn))} house of this chart, which is a house that matters for ${A.short}.` : '';
      const full = key2 || strong || weak || vg;
      const text = `${n} is in ${SIGN[sIdx]}, in the ${ordn(h)} house of this chart${tag}.${vtag}${role}${rule} ${m.practice[0].line}` + (full ? ` At its best, you ${B.atBest}; under strain, you may ${B.underStress}.` : '');
      return { planet: n, sign: SIGN[sIdx], signIndex: sIdx, house: h, dignity: st, strong, weak, vargottama: vg, key: key2, rules: ruled, text };
    });
    // ---- domain houses
    const houses = A.houses.map(h => {
      const s = (lagSign + h - 1) % 12, lord = S[s].lord, ls = pvs[lord], lh = ls != null ? houseOfSign(ls) : null, occ = hs[h - 1].planets.map(p => p.name), ar = VMF.data.arena[h - 1];
      const ld = ls != null ? dg(lord) : 'Neutral', ldTxt = ld === 'Exalted' || ld === 'OwnSign' || ld === 'Moolatrikona' ? ', in a strong sign' : ld === 'Debilitated' ? ', in a weaker sign' : '';
      const ben = occ.filter(n => BEN.includes(n)), mal = occ.filter(n => !BEN.includes(n));
      const oc = !occ.length ? 'No planet sits there, so its lord carries the house.' : `${nm(occ)} ${occ.length > 1 ? 'sit' : 'sits'} there${ben.length && !mal.length ? ', which tends to support it' : mal.length && !ben.length ? ', which tends to add pressure there' : ', a mix of supportive and demanding influences'}.`;
      return { house: h, sign: SIGN[s], lord, lordHouse: lh, lordDignity: ld, occupants: occ, text: `The ${ordn(h)} house of this chart (${ar.theme}) is ${SIGN[s]}, ruled by ${lord}, which stands in ${SIGN[ls]} in the ${ordn(lh)} house${ldTxt}. ${oc}` };
    });
    // ---- strength summary and score
    const strong = planets.filter(p => p.strong).map(p => p.planet), weak = planets.filter(p => p.weak).map(p => p.planet), vgs = planets.filter(p => p.vargottama).map(p => p.planet);
    let num = 0, den = 0; planets.forEach(p => { const w = p.key ? 2 : 1; num += w * (DIG[p.dignity] || 0) + (p.vargottama && p.key ? 0.3 : 0) * w; den += w; });
    const lordsAvg = houses.length ? houses.reduce((a, x) => a + (DIG[x.lordDignity] || 0), 0) / houses.length : 0, occAvg = houses.reduce((a, x) => a + x.occupants.reduce((b, n) => b + (BEN.includes(n) ? 0.3 : -0.2), 0), 0) / Math.max(1, houses.length);
    const score = Math.round(clamp(50 + 22 * (den ? num / den : 0) + 14 * lordsAvg + 10 * occAvg, 3, 97)), band = BANDS.find(b => score >= b[0]);
    const summary = { strong, weak, vargottama: vgs, text: `${strong.length ? 'Comfortable here: ' + nm(strong) + '. ' : ''}${weak.length ? 'Under some strain here: ' + nm(weak) + '. ' : ''}${vgs.length ? 'Same sign as in your birth chart (vargottama): ' + nm(vgs) + '. ' : ''}${!strong.length && !weak.length ? 'No planet is in a notably strong or weak sign, so this chart works mostly through placement. ' : ''}Overall this chart reads as ${band[1].toLowerCase()} for ${A.short} (${score}/100).`.trim() };
    // ---- text
    const lagText = `The ${A.name} rises in ${SIGN[lagSign]}: ${S[lagSign].style}. ${A.lagna} ${S[lagSign].name} is ruled by ${S[lagSign].lord}${pvs[S[lagSign].lord] != null ? ', which stands in ' + SIGN[pvs[S[lagSign].lord]] + ' here' : ''}.`;
    const paragraphs = [{ h: 'What this chart shows', text: A.intro }, { h: 'How it begins', text: lagText }, { h: `The houses that matter for ${A.short}`, text: houses.map(x => x.text).join(' ') },
      { h: 'Planet by planet', text: planets.map(p => p.text).join(' ') }, { h: 'Strength at a glance', text: summary.text }, { h: 'Check this against your life', text: A.asks.join(' ') }];
    return { key, name: A.name, short: A.short, noun: A.noun, score, band: band[1], bandTone: band[2], lagna: { sign: SIGN[lagSign], text: lagText }, houses, planets, summary, questions: A.asks.slice(), paragraphs, words: words(paragraphs.map(p => p.text).join(' ')),
      text: `${A.name}\n` + paragraphs.map(p => `${p.h}. ${p.text}`).join('\n\n') };
  }
  function all(c){ return D.order.map(k => chart(c, k)).filter(Boolean); }
  return { data: D, chart, all, keys: D.order };
})(VGR_DATA);
'''
out = HEAD + json.dumps(DATA, ensure_ascii=False, indent=1) + ';' + API
open(os.path.join(REPO, 'apps/birth-chart/js/96-varga-reading.js'), 'w', encoding='utf-8').write(out)
print('written KB:', len(out.encode()) // 1024)
